    "description": "നിങ്ങളുടെ സ്കൂളിലേക്കോ കോർപ്പറേറ്റ് ഓഫീസിലേക്കോ സൊസൈറ്റിയിലേക്കോ കമ്മ്യൂണിറ്റിയിലേക്കോ EMA Fight Back പരിശീലനം കൊണ്ടുവരിക. People Safety, ഭീഷണിപ്പെടുത്തൽ തടയൽ, അല്ലെങ്കിൽ സ്വയം പ്രതിരോധ ശിൽപശാല എന്നിവ ഷെഡ്യൂൾ ചെയ്യുന്നതിന് ചുവടെയുള്ള ഫോം പൂരിപ്പിക്കുക. വിശദാംശങ്ങൾ സ്ഥിരീകരിക്കുന്നതിനും നിങ്ങളുടെ ഗ്രൂപ്പിനായി ശരിയായ പ്രോഗ്രാം തിരഞ്ഞെടുക്കാൻ സഹായിക്കുന്നതിനും ഞങ്ങളുടെ ടീം 24 മണിക്കൂറിനുള്ളിൽ നിങ്ങളെ ബന്ധപ്പെടും.",
    "seeWorkshops": "വർക്ക്ഷോപ്പ് തരങ്ങൾ കാണുക",
    "intro": "നിങ്ങൾക്ക് അനുയോജ്യമായ ഫോം തിരഞ്ഞെടുക്കുക. വിശദമായ ചോദ്യങ്ങൾ - ആശങ്കകൾ, സമയം, ബജറ്റ്, മുൻ അനുഭവം - കൺസൾട്ടൻസിയിൽ ഉൾപ്പെടുന്നു.",
    "personalTitle": "വ്യക്തിഗത സുരക്ഷാ കൺസൾട്ടൻസി",
